; sysvars.asm -- chapter 3: the registers at INIT and the BIOS's work area
; generated by gen03.py
        INCLUDE "msx.inc"
        OUTPUT "sysvars.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
r_af    EQU VARS + 16           ; the registers as the cartridge found them
r_bc    EQU VARS + 18
r_de    EQU VARS + 20
r_hl    EQU VARS + 22
r_ix    EQU VARS + 24
r_iy    EQU VARS + 26
r_sp    EQU VARS + 28
r_i     EQU VARS + 30           ; I, then the flags of LD A,I
init:   ld (r_sp), sp           ; before anything changes them
        push af
        ld (r_bc), bc
        ld (r_de), de
        ld (r_hl), hl
        ld (r_ix), ix
        ld (r_iy), iy
        pop hl
        ld (r_af), hl
        ld a, i                 ; P/V: the interrupt enable flip-flop IFF2
        ld (r_i), a
        push af
        pop hl
        ld a, l
        ld (r_i + 1), a
        di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while the page is drawn
        VDP_REG 0, $00          ; Graphic I: 32 x 24 characters
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $80          ; colours            $2000
        VDP_REG 4, $00          ; patterns           $0000
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; the BIOS character set: 256 x 8 bytes
        ld hl, (CGTABL)
        ld bc, 2048
.font:  ld a, (hl)
        out (VDP_DATA), a
        inc hl
        dec bc
        ld a, b
        or c
        jr nz, .font
        VRAM_WRITE $0008        ; characters 1 and 2: the bit boxes
        ld hl, boxes
        ld b, 16
.box:   ld a, (hl)
        out (VDP_DATA), a
        inc hl
        djnz .box
        VRAM_WRITE $2000        ; colours: black ink (1) on white paper (15)
        ld b, 32
        ld a, $1F
.col:   out (VDP_DATA), a
        djnz .col
        VRAM_WRITE $1800        ; names: all spaces
        ld bc, 768
.clr:   ld a, ' '
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .clr
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        ld b, 1
        ld c, 0
        ld hl, t_head
        call puts
        ld b, 3
        ld c, 0
        ld hl, n0
