.iff:   call putc
        VDP_REG 1, $C0          ; display on: the page is finished
done:   jr done

; bytes: E bytes from HL, in hexadecimal, a space between. C moves on.
bytes:  ld a, (hl)
        call puthex
        inc c
        inc hl
        dec e
        jr nz, bytes
        ret

t_head: db "name   addr  value", 0
t_regs: db "the registers at INIT", 0
t_i:    db "I  ", 0
t_iff:  db "interrupts on (IFF2): ", 0
n0:     db "BOTTOM", 0
n1:     db "HIMEM", 0
n2:     db "STKTOP", 0
n3:     db "EXPTBL", 0
n4:     db "CGPNT", 0
n5:     db "SCRMOD", 0
n6:     db "FORCLR", 0
n7:     db "RG0SAV", 0
n8:     db "RG4SAV", 0
n9:     db "STATFL", 0
n10:     db "JIFFY", 0
n11:     db "CLIKSW", 0
n12:     db "H.KEYI", 0
n13:     db "H.TIMI", 0
rn0:    db "AF ", 0
rn1:    db "BC ", 0
rn2:    db "DE ", 0
rn3:    db "HL ", 0
rn4:    db "IX ", 0
rn5:    db "IY ", 0
rn6:    db "SP ", 0

; at: B = row (0-23), C = column (0-31) -> the VDP's write address is that
;     cell of the name table. Keeps BC, DE. Uses A, HL.
at:     push de
        ld l, b
        ld h, 0
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl              ; row x 32
        ld e, c
        ld d, $18
        add hl, de              ; + $1800 + column
        ld a, l
        out (VDP_CTRL), a
        ld a, h
        or $40
        out (VDP_CTRL), a
        pop de
        ret

; putc: A = character, B = row, C = column. Keeps BC, DE, HL.
putc:   push hl
        push af
        call at
        pop af
        out (VDP_DATA), a
        pop hl
        ret

; puts: HL = text ending in 0, B = row, C = column; C moves on.
puts:   ld a, (hl)
        or a
        ret z
        call putc
        inc hl
        inc c
        jr puts

; puthex: A = a byte, as two hexadecimal digits; C moves on by 2.
puthex: push af
        rrca
        rrca
        rrca
        rrca                    ; the high four bits first
        call hexdig
        pop af
hexdig: and %00001111
        add a, '0'
        cp '9' + 1
        jr c, .digit
        add a, 'A' - '9' - 1    ; 10-15 become A-F
.digit: call putc
        inc c
        ret
boxes:                          ; characters 1 (empty box) and 2 (filled)
        db %11111110, %10000010, %10000010, %10000010, %10000010, %10000010, %11111110, %00000000
        db %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %00000000
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
